#include<bits/stdc++.h>
using namespace std;

int main(){
	int N; cin >> N;
	vector<string> S(N),T(N);
	string ans = "No";
	for(int i=0; i<N; i++){
		cin >> S[i] >> T[i];
		for(int j=0; j<i; j++){
			if(S[i]==S[j] && T[i]==T[j]) ans = "Yes";
		}
	}
	cout << ans << endl;
}

N = int(input())
S = ['']*N
T = ['']*N
for i in range(N):
    S[i],T[i] = map(str,input().split())
ans = 'No'
for i in range(N):
    for j in range(i+1,N):
        if S[i]==S[j] and T[i]==T[j]:
            ans = 'Yes'
print(ans)
